def rng(q):
    q = sorted(set(q)); out = []; i = 0
    while i < len(q):
        j = i
        while j + 1 < len(q) and q[j + 1] == q[j] + 1: j += 1
        out.append(str(q[i]) if i == j else ('%d–%d' % (q[i], q[j]) if j > i + 1 else '%d, %d' % (q[i], q[j]))); i = j + 1
    return ', '.join(out)
