rows = []
for d, _, fs in os.walk(S):
    for f in fs:
        p = os.path.join(d, f)
        if f in ('.gitkeep', 'Контрольные суммы SHA-256.txt', 'Реестр источников.md', 'Литература и материалы по вопросам.md'): continue
        rows.append((p[len(S):], hashlib.sha256(open(p, 'rb').read()).hexdigest()))
rows.sort()
open(S + 'Контрольные суммы SHA-256.txt', 'w', encoding='utf-8').write(''.join('%s  %s\n' % (h, p) for p, h in rows))
